package com.ejemplo.alquileres.controller;
import com.ejemplo.alquileres.model.TipoInmueble; import com.ejemplo.alquileres.service.TipoInmuebleService; import com.ejemplo.alquileres.ui.*;
import javafx.beans.property.SimpleStringProperty; import javafx.collections.*; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.layout.VBox; import org.springframework.data.domain.Page; import org.springframework.stereotype.Component;
@Component public class TipoInmuebleController implements Refrescable {
 private final TipoInmuebleService service; private final Tareas tareas; private final Notificador aviso; private final ObservableList<TipoInmueble> datos=FXCollections.observableArrayList(); private Long id;
 @FXML private TextField buscar,codigo,nombre; @FXML private TextArea descripcion; @FXML private TableView<TipoInmueble> tabla; @FXML private TableColumn<TipoInmueble,String> colCodigo,colNombre,colEstado; @FXML private VBox drawer; @FXML private Label titulo;
 public TipoInmuebleController(TipoInmuebleService s,Tareas t,Notificador a){service=s;tareas=t;aviso=a;}
 @FXML public void initialize(){colCodigo.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getCodigo()));colNombre.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getNombre()));colEstado.setCellValueFactory(c->new SimpleStringProperty(c.getValue().isActivo()?"Activo":"Inactivo"));tabla.setItems(datos);tabla.setOnMouseClicked(e->{if(e.getClickCount()==2)editar(tabla.getSelectionModel().getSelectedItem());});buscar.textProperty().addListener((o,a,b)->refrescar());}
 public void refrescar(){tareas.ejecutar(()->service.listar(buscar.getText(),0,100),this::mostrar,e->aviso.error(mensaje(e)));} private void mostrar(Page<TipoInmueble> p){datos.setAll(p.getContent());}
 @FXML private void onNuevo(){id=null;codigo.clear();nombre.clear();descripcion.clear();titulo.setText("Nuevo tipo de inmueble");drawer.setVisible(true);drawer.setManaged(true);}
 @FXML private void onEditar(){editar(tabla.getSelectionModel().getSelectedItem());} private void editar(TipoInmueble t){if(t==null)return;id=t.getId();codigo.setText(t.getCodigo());nombre.setText(t.getNombre());descripcion.setText(t.getDescripcion()==null?"":t.getDescripcion());titulo.setText("Editar tipo de inmueble");drawer.setVisible(true);drawer.setManaged(true);}
 @FXML private void onGuardar(){TipoInmueble t=TipoInmueble.builder().id(id).codigo(codigo.getText()).nombre(nombre.getText()).descripcion(descripcion.getText()).activo(true).build();tareas.ejecutar(()->service.guardar(t),x->{cerrar();aviso.info("Tipo de inmueble guardado.");refrescar();},e->aviso.error(mensaje(e)));}
 @FXML private void onEliminar(){TipoInmueble t=tabla.getSelectionModel().getSelectedItem();if(t==null)return;tareas.ejecutar(()->{service.eliminar(t.getId());return null;},x->{aviso.info("Tipo eliminado o desactivado según sus referencias.");refrescar();},e->aviso.error(mensaje(e)));}
 @FXML private void onCerrar(){cerrar();} private void cerrar(){drawer.setVisible(false);drawer.setManaged(false);} private String mensaje(Throwable e){return e.getCause()!=null?e.getCause().getMessage():e.getMessage();}
}
